@Service
public class RequestCounterService {
    private int requestCount = 0; // shared mutable state

    public void incrementRequestCount() {
        requestCount++; // NOT atomic - three operations: read, add, write
    }

    public int getRequestCount() {
        return requestCount;
    }
}

// Scenario: two threads call incrementRequestCount() simultaneously
// Thread A: reads 10, adds 1, paused before writing
// Thread B: reads 10 (still!), adds 1, writes 11
// Thread A: resumes, writes 11 (lost Thread B's update!)
// Expected: 12, Actual: 11 — this is a race condition

// Fixed version:
private final AtomicInteger requestCount = new AtomicInteger(0);
public void incrementRequestCount() {
    requestCount.incrementAndGet(); // atomic operation
}
