public class TaskQueue {
    private final Queue<Task> tasks = new LinkedList<>();
    private final Object lock = new Object();

    public void addTask(Task task) {
        synchronized (lock) {
            tasks.add(task);
            lock.notify(); // Problem: only wakes ONE waiting thread
        }
    }

    public Task getTask() throws InterruptedException {
        synchronized (lock) {
            while (tasks.isEmpty()) {
                lock.wait(); // Multiple worker threads waiting here
            }
            return tasks.poll();
        }
    }
}
// Issue: If 5 threads wait and notify only wakes one,
// the JVM might always pick the same thread to wake.
// The other 4 threads starve.
// Fix: use lock.notifyAll() to wake all waiting threads
