public class VisitorCounter {
    private int count = 0; // shared mutable field

    public void incrementVisitor() {
        count++; // Compiles to: load count, add 1, store count
    }

    public int getCount() {
        return count;
    }
}

// Bytecode-level interleaving:
// Initial count = 10
// Thread A: load count (reads 10)
// Thread A: add 1 (calculates 11, not yet stored)
// [CONTEXT SWITCH]
// Thread B: load count (reads 10 — A hasn't written yet!)
// Thread B: add 1 (calculates 11)
// Thread B: store count (writes 11)
// [CONTEXT SWITCH]
// Thread A: store count (writes 11 — overwrites B's update!)
// Result: 11 instead of 12

// Fix with AtomicInteger:
private final AtomicInteger count = new AtomicInteger(0);
public void incrementVisitor() {
    count.incrementAndGet(); // single atomic CPU instruction
}
