public class AccountService {
    private final Object lockA = new Object();
    private final Object lockB = new Object();

    public void transferFromAToB() {
        synchronized (lockA) { // Thread 1 acquires lockA
            System.out.println("Thread 1: holding lockA");
            Thread.sleep(100); // simulate work
            synchronized (lockB) { // Thread 1 waits for lockB (held by Thread 2)
                System.out.println("Transfer A to B");
            }
        }
    }

    public void transferFromBToA() {
        synchronized (lockB) { // Thread 2 acquires lockB
            System.out.println("Thread 2: holding lockB");
            Thread.sleep(100);
            synchronized (lockA) { // Thread 2 waits for lockA (held by Thread 1)
                System.out.println("Transfer B to A");
            }
        }
    }
    // Deadlock: Thread 1 waits for lockB, Thread 2 waits for lockA
    // Fix: always acquire locks in same order (lockA then lockB)
}
