public class ConfigurationLoader {
    private boolean configLoaded = false; // NOT volatile
    private Properties config;

    // Thread A: loads configuration
    public void loadConfig() {
        config = loadPropertiesFromFile(); // Step 1: load data
        configLoaded = true; // Step 2: set flag
        // Without volatile, Thread B might see configLoaded=true
        // but config is still null due to reordering or cache!
    }

    // Thread B: uses configuration
    public String getProperty(String key) {
        if (configLoaded) { // Might see true
            return config.getProperty(key); // But config might be null!
        }
        return null;
    }
}

// Fixed version with volatile:
private volatile boolean configLoaded = false;
// volatile ensures happens-before:
// All writes before writing configLoaded
// are visible to all reads after reading configLoaded
